impl TimelineAuthoringService {
    /// Starts a session around a current-format document.
    pub fn new(document: TimelineDocument) -> Result<Self, TimelineAuthoringError> {
        let diagnostics = validate_timeline(&document);
        if has_errors(&diagnostics) {
            return Err(TimelineAuthoringError::Invalid(diagnostics));
        }
        static NEXT_GENERATION: AtomicU64 = AtomicU64::new(1);
        Ok(Self {
            document,
            revision: 0,
            generation: NEXT_GENERATION.fetch_add(1, Ordering::Relaxed),
            undo: Vec::new(),
            redo: Vec::new(),
        })
    }

    /// Current immutable document.
    pub const fn document(&self) -> &TimelineDocument { &self.document }
    /// Current optimistic revision.
    pub const fn revision(&self) -> TimelineRevision { self.revision }
    /// Current live-session generation.
    pub const fn generation(&self) -> u64 { self.generation }

    /// Inspects the committed Timeline through the shared permission boundary.
    pub fn inspect(&self, permissions: &AuthoringPermissions) -> Result<TimelineAuthoringSnapshot, TimelineAuthoringError> {
        permissions.require(AuthoringPermission::Read)?;
        Ok(TimelineAuthoringSnapshot { revision: self.revision, generation: self.generation, document: self.document.clone() })
    }

    /// Validates the committed Timeline without mutation.
    pub fn validate(&self, permissions: &AuthoringPermissions) -> Result<TimelineAuthoringValidation, TimelineAuthoringError> {
        permissions.require(AuthoringPermission::Read)?;
        let diagnostics = validate_timeline(&self.document);
        Ok(TimelineAuthoringValidation { revision: self.revision, generation: self.generation, success: !has_errors(&diagnostics), diagnostics })
    }

    /// Previews one atomic structured command batch without mutation or history changes.
    pub fn preview_commands(&self, permissions: &AuthoringPermissions, expected_revision: TimelineRevision, expected_generation: u64, commands: Vec<TimelineAuthoringCommand>) -> Result<TimelineAuthoringMutation, TimelineAuthoringError> {
        permissions.require(AuthoringPermission::Preview)?;
        self.check_base(expected_revision, expected_generation)?;
        let candidate = candidate_from_commands(&self.document, commands)?;
        let diagnostics = validate_timeline(&candidate);
        let success = !has_errors(&diagnostics);
        Ok(TimelineAuthoringMutation { success, base_revision: expected_revision, base_generation: expected_generation, revision: self.revision, generation: self.generation, diagnostics, diff: document_diff(&self.document, &candidate) })
    }

    /// Applies one atomic structured command batch through the shared permission boundary.
    pub fn apply_commands(&mut self, permissions: &AuthoringPermissions, expected_revision: TimelineRevision, expected_generation: u64, commands: Vec<TimelineAuthoringCommand>) -> Result<TimelineAuthoringMutation, TimelineAuthoringError> {
        permissions.require(AuthoringPermission::ProjectDataWrite)?;
        self.check_base(expected_revision, expected_generation)?;
        let candidate = candidate_from_commands(&self.document, commands)?;
        let diagnostics = validate_timeline(&candidate);
        let success = !has_errors(&diagnostics);
        let diff = document_diff(&self.document, &candidate);
        if !success {
            return Ok(TimelineAuthoringMutation { success: false, base_revision: expected_revision, base_generation: expected_generation, revision: self.revision, generation: self.generation, diagnostics, diff });
        }
        if !diff.is_empty() {
            self.undo.push(self.document.clone());
            self.document = candidate;
            self.redo.clear();
            self.advance_live_state();
        }
        Ok(TimelineAuthoringMutation { success: true, base_revision: expected_revision, base_generation: expected_generation, revision: self.revision, generation: self.generation, diagnostics, diff })
    }

    /// Validates one command against a clone without mutation.
    pub fn preview(&self, expected: TimelineRevision, command: &TimelineAuthoringCommand) -> Result<TimelineAuthoringPreview, TimelineAuthoringError> {
        self.check_revision(expected)?;
        let mut candidate = self.document.clone();
        apply_command(&mut candidate, command)?;
        let diagnostics = validate_timeline(&candidate);
        Ok(TimelineAuthoringPreview { document: candidate, diagnostics })
    }

    /// Atomically applies one command after validation.
    pub fn apply(&mut self, expected: TimelineRevision, command: TimelineAuthoringCommand) -> Result<TimelineRevision, TimelineAuthoringError> {
        self.apply_transaction(expected, std::iter::once(command))
    }

    /// Atomically applies a granular command transaction with one undo boundary.
    ///
    /// This compatibility entry point is retained for existing Editor code. New
    /// structured adapters use [`Self::apply_commands`] so permissions and the
    /// generation token are enforced at the shared boundary.
    pub fn apply_transaction(&mut self, expected: TimelineRevision, commands: impl IntoIterator<Item = TimelineAuthoringCommand>) -> Result<TimelineRevision, TimelineAuthoringError> {
        self.check_revision(expected)?;
        let candidate = candidate_from_commands(&self.document, commands)?;
        let diagnostics = validate_timeline(&candidate);
        if has_errors(&diagnostics) { return Err(TimelineAuthoringError::Invalid(diagnostics)); }
        self.undo.push(self.document.clone());
        self.document = candidate;
        self.redo.clear();
        self.advance_live_state();
        Ok(self.revision)
    }

    /// Undoes one committed transaction.
    pub fn undo(&mut self) -> bool {
        let Some(previous) = self.undo.pop() else { return false; };
        self.redo.push(std::mem::replace(&mut self.document, previous));
        self.advance_live_state();
        true
    }
    /// Redoes one undone transaction.
    pub fn redo(&mut self) -> bool {
        let Some(next) = self.redo.pop() else { return false; };
        self.undo.push(std::mem::replace(&mut self.document, next));
        self.advance_live_state();
        true
    }
    /// Persists the committed source of truth.
    pub fn save(&self, path: &Path) -> Result<(), TimelineAuthoringError> { save_timeline(path, &self.document).map_err(|error| TimelineAuthoringError::Persist(error.to_string())) }

    fn advance_live_state(&mut self) { self.revision = self.revision.wrapping_add(1); self.generation = self.generation.wrapping_add(1); }
    fn check_revision(&self, actual: TimelineRevision) -> Result<(), TimelineAuthoringError> { if actual == self.revision { Ok(()) } else { Err(TimelineAuthoringError::StaleRevision { expected: self.revision, actual }) } }
    fn check_base(&self, expected_revision: TimelineRevision, expected_generation: u64) -> Result<(), TimelineAuthoringError> {
        if expected_revision == self.revision && expected_generation == self.generation { return Ok(()); }
        Err(TimelineAuthoringError::Stale { expected_revision, expected_generation, actual_revision: self.revision, actual_generation: self.generation })
    }
}

